INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(8201, '1 Kings 1:21', '1 Kings', 1, 21, '&nbsp;کۀ تۀ داسې ونۀ کړې نو چې تۀ څنګه وفات شې نو ما سره او زما د زوئ سليمان سره به د مجرمانو په شان سلوک کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8202, '1 Kings 1:22', '1 Kings', 1, 22, '&nbsp;د هغې خبرې جارى وې چې ناتن محل ته راورسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8203, '1 Kings 1:23', '1 Kings', 1, 23, '&nbsp;بادشاه خبر شو چې پېغمبر هلته دے، ناتن لاړو او د بادشاه په مخکښې ټيټ شو او پړمخې پرېوتو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8204, '1 Kings 1:24', '1 Kings', 1, 24, '&nbsp;بيا هغۀ وفرمائيل، ”بادشاه سلامت، تا دا اِعلان کړے دے چې ستا نه پس به ادونياه بادشاه وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8205, '1 Kings 1:25', '1 Kings', 1, 25, '&nbsp;هغه نن تلے دے او د غوَيانو، ګډو او د څربو سخو قربانى يې پېش کړې ده. هغۀ ستا ټولو زامنو، ستا د لښکر مشر يوآب او ابياتار اِمام له دعوت ورکړے دے او وګوره هغوئ د هغۀ سره په روټۍ کښې شريک دى او چغې وهى چې ادونياه بادشاه زنده‌باد.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8206, '1 Kings 1:26', '1 Kings', 1, 26, '&nbsp;خو بادشاه سلامت، هغۀ ما، صدوق اِمام، بناياه او سليمان له دعوت رانۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8207, '1 Kings 1:27', '1 Kings', 1, 27, '&nbsp;بادشاه سلامت، تا د دې مېلمستيا اجازت ورکړے دے؟ خپلو وزيرانو او آفسرانو ته دې هم ونۀ وئيل چې ستا نه پس به بادشاه څوک وى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8208, '1 Kings 1:28', '1 Kings', 1, 28, '&nbsp;داؤد بادشاه وفرمائيل، ”بت‌‌سبع ته ووايئ چې دننه راشى.“ نو راغله او د هغۀ په مخکښې ودرېده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8209, '1 Kings 1:29', '1 Kings', 1, 29, '&nbsp;بيا هغۀ ورته وفرمائيل، ”زۀ تا ته د ژوندى مالِک خُدائ په نوم قسم کوم، چې هغۀ زۀ د ټولو مصيبتونو نه بچ کړے يم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8210, '1 Kings 1:30', '1 Kings', 1, 30, '&nbsp;نن به زۀ تا سره هغه لوظ پوره کوم چې ما درسره د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک په نوم کړے دے، چې ستا زوئ سليمان به زما نه پس هم نن د بادشاهۍ په تخت کښېنى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8211, '1 Kings 1:31', '1 Kings', 1, 31, '&nbsp;بت‌‌سبع ورته ټيټه شوه، پړمخې پرېوتله او وې وئيل، ”بادشاه سلامت دې تل تر تله ژوندے وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8212, '1 Kings 1:32', '1 Kings', 1, 32, '&nbsp;بيا داؤد بادشاه صدوق اِمام، ناتن پېغمبر او د يهويدع بناياه راغوښتل. کله چې هغوئ دننه راغلل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8213, '1 Kings 1:33', '1 Kings', 1, 33, '&nbsp;نو هغۀ ورته وفرمائيل، ”زما د دربار آفسران د ځان سره بوځئ، زما زوئ سليمان دې زما په قچره باندې سور شى او لاندې د جيحون چينې پورې د هغۀ ملګرتيا وکړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8214, '1 Kings 1:34', '1 Kings', 1, 34, '&nbsp;چرته چې صدوق اِمام او ناتن پېغمبر هغه د بنى اِسرائيلو د بادشاه په توګه سر په تېلو غوړ کړى نو بيا بيګل وغږوئ او چغې کړئ چې سليمان بادشاه زنده‌باد.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8215, '1 Kings 1:35', '1 Kings', 1, 35, '&nbsp;په هغۀ پسې واپس دلته راشئ چې کله هغه زما په تخت باندې د کښېناستو دپاره راځى. هغه به زما نه پس بادشاه وى، ځکه چې هغه ما خوښ کړے دے چې د اِسرائيل او يهوداه بادشاه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8216, '1 Kings 1:36', '1 Kings', 1, 36, '&nbsp;بناياه ورته ووئيل، ”هم داسې به وشى او مالِک خُدائ ستا خُدائ پاک دې دا خبره يقينى کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8217, '1 Kings 1:37', '1 Kings', 1, 37, '&nbsp;بادشاه سلامت، څنګه چې مالِک خُدائ ستا مل دے نو د سليمان دې هم مل شى او د هغۀ بادشاهى دې ستا نه هم زياته بختوره کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8218, '1 Kings 1:38', '1 Kings', 1, 38, '&nbsp;نو صدوق، ناتن او بناياه روان شول او د داؤد محافظان يې د ځان سره کړل. سليمان د داؤد بادشاه په قچره سور وو او د جيحون چينې پورې يې د هغۀ ملګرتيا وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8219, '1 Kings 1:39', '1 Kings', 1, 39, '&nbsp;صدوق د زيتُونو هغه تېل واخستل چې کوم يې د مالِک خُدائ د حضور د خېمې نه راوړى وُو او د سليمان سر يې په تېلو غوړ کړو. هغوئ بيګل وغږولو او ټولو خلقو چغه کړه، ”سليمان بادشاه زنده‌باد.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8220, '1 Kings 1:40', '1 Kings', 1, 40, '&nbsp;بيا ټول خلق ورپسې روان شول، د خوشحالۍ نه يې چغې وهلې او شپېلۍ يې غږولې، دومره زيات شور يې کولو چې زمکه يې خوځوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8221, '1 Kings 1:41', '1 Kings', 1, 41, '&nbsp;کله چې ادونياه او د هغۀ ټولو مېلمنو روټۍ ختموله، نو هغوئ شور واورېدو. او کله چې يوآب د بيګل آواز واورېدو نو تپوس يې وکړو، ”په ښار کښې د دې شور څۀ مطلب دے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8222, '1 Kings 1:42', '1 Kings', 1, 42, '&nbsp;هغۀ لا خبره ختمه کړې نۀ وه چې د ابياتار اِمام زوئ يونتن راورسېدو. ادونياه ورته ووئيل، ”دننه راشه، ستا په شان ښۀ سړے به خامخا يو ښۀ زېرے راوړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8223, '1 Kings 1:43', '1 Kings', 1, 43, '&nbsp;يونتن ورته ووئيل، ”نه، دا خبره نشته داؤد سليمان بادشاه جوړ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8224, '1 Kings 1:44', '1 Kings', 1, 44, '&nbsp;هغۀ صدوق، ناتن، بناياه او شاهى محافظان راوغوښتل چې د هغۀ ملګرتيا وکړى. هغوئ هغه د بادشاه په قچره باندې سور کړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8225, '1 Kings 1:45', '1 Kings', 1, 45, '&nbsp;صدوق او ناتن هغه د جيحون چينې سره د بادشاه په توګه مقرر کړو. بيا هغوئ ښار ته لاړل، د خوشحالۍ نه يې دا چغې وهلې چې اوس خلق په جوش کښې دى. دا هغه شور دے چې تۀ يې اورې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8226, '1 Kings 1:46', '1 Kings', 1, 46, '&nbsp;نو سليمان اوس بادشاه شوے دے او د بادشاهۍ په تخت ناست دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8227, '1 Kings 1:47', '1 Kings', 1, 47, '&nbsp;بله خبره دا چې د دربار آفسران خپل بادشاه داؤد له عزت ورکولو دپاره دننه ورغلل او ورته يې ووئيل، ستا خُدائ پاک دې سليمان ستا نه هم زيات مشهور کړى او د سليمان بادشاهى دې ستا نه هم زياته بختوره شى. بيا داؤد بادشاه په خپل کټ کښې د عبادت دپاره ټيټ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8228, '1 Kings 1:48', '1 Kings', 1, 48, '&nbsp;او بادشاه دا هم وفرمائيل، راځئ، د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک ثناء صِفت وکړُو، چې هغۀ زما د اولاد نه يو کس زما نه پس بادشاه جوړ کړو او هغۀ زۀ ژوندے پرېښودم چې دا وګورم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8229, '1 Kings 1:49', '1 Kings', 1, 49, '&nbsp;بيا د ادونياه ټول مېلمانۀ ويرېدل، هغوئ پاڅېدل او لاړل، هر يو په خپله مخه لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8230, '1 Kings 1:50', '1 Kings', 1, 50, '&nbsp;ادونياه چې د سليمان نه سخت په يره کښې وو، هغه د مالِک خُدائ د حضور خېمې ته تېز لاړو او د خپل ژوند بچ کولو دپاره د قربان‌ګاه ښکر يې ونيول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8231, '1 Kings 1:51', '1 Kings', 1, 51, '&nbsp;سليمان بادشاه خبر شو چې ادونياه د هغۀ نه ويرېدو او د قربان‌ګاه ښکر يې ونيول او ادونياه وئيل، ”وړومبۍ خبره دا ده چې سليمان بادشاه ما ته قسم وکړى چې هغه به ما نۀ وژنى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8232, '1 Kings 1:52', '1 Kings', 1, 52, '&nbsp;سليمان ورته وفرمائيل، ”کۀ هغه وفادار وى، نو د هغۀ د سر يو وېښتۀ به هم نۀ ضائع کيږى، خو کۀ هغه لانجې جوړوى، نو مړ به شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8233, '1 Kings 1:53', '1 Kings', 1, 53, '&nbsp;سليمان بادشاه ادونياه راغوښتو او د قربان‌ګاه نه راکوز کړے شو. ادونياه بادشاه له لاړو او د هغۀ په مخکښې ټيټ شو او بادشاه هغۀ ته وفرمائيل، ”تۀ کور ته ځان ورسوه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8234, '1 Kings 2:1', '1 Kings', 2, 1, '&nbsp;کله چې داؤد د مرګ په حالت کښې وو، نو هغۀ خپل زوئ سليمان راوغوښتلو او وصيت يې ورته وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8235, '1 Kings 2:2', '1 Kings', 2, 2, '&nbsp;”زما وخت پوره دے، تکړه سړے شه او حوصله مضبوطه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8236, '1 Kings 2:3', '1 Kings', 2, 3, '&nbsp;او هغه څۀ کوه چې مالِک خُدائ ستا خُدائ پاک يې حُکم درکوى. او د هغۀ ټول قانون او حُکمونه منه، لکه څنګه چې د موسىٰ په شريعت کښې ليکلے شوى دى، بيا چې چرته هم ځې نو په هر کار کښې به کامياب يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8237, '1 Kings 2:4', '1 Kings', 2, 4, '&nbsp;کۀ تۀ د هغۀ فرمانبردارى کوې نو مالِک خُدائ به هغه لوظ پوره کړى چې ما ته يې فرمائيلى وُو چې زما اولاد به تر هغې پورې په بنى اِسرائيلو بادشاهى کوى چې هغوئ په وفادارۍ سره د زړۀ د اخلاصه د هغۀ حُکمونه منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8238, '1 Kings 2:5', '1 Kings', 2, 5, '&nbsp;د دې نه علاوه تا ته پته ده چې يوآب زما سره څۀ وکړل چې د بنى اِسرائيلو د لښکر دوه مشران يې ووژل، يعنې د نير زوئ ابنير او د يتر زوئ عماسا. تا ته ياد دى چې هغوئ يې د امن په وخت کښې د بدل اخستلو دپاره ووژل. يوآب بې‌ګناه سړى ووژل او چې څۀ يې کړى وُو نو ذمه وارى يې په خپل سر ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8239, '1 Kings 2:6', '1 Kings', 2, 6, '&nbsp;د خپل عقل نه کار واخله، هغه مۀ پرېږده چې سپين‌ږيرے شى او په خپل مرګ مړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8240, '1 Kings 2:7', '1 Kings', 2, 7, '&nbsp;خو د جِلعاد د برزلى زامنو ته خپله مِهربانى وښايه او د هغوئ خيال وساته، ځکه چې زۀ کله ستا ورور ابى‌سلوم نه تښتېدم نو هغوئ په ما مهربانه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8241, '1 Kings 2:8', '1 Kings', 2, 8, '&nbsp;په بنيامين کښې د بحوريم ښار د جيرا زوئ سِمعى هم دے. کله چې زۀ محنايم ته تلم نو هغۀ ما ته سختې ښېرې کولې، خو چې کله هغه د اُردن سيند سره ما سره مِلاو شو، نو ما د مالِک خُدائ په نوم د سِمعى سره پوخ لوظ وکړو چې زۀ به هغه نۀ وژنم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8242, '1 Kings 2:9', '1 Kings', 2, 9, '&nbsp;تر څو چې دې سزا نۀ وى ورکړې چې هغه پرې نۀ ږدې. ځکه چې تۀ د حِکمت خاوند يې او تا ته به پته ولګى چې څۀ کول په کار دى، او تۀ به دا خبره يقينى کوې چې هغه په سخت مرګ مړ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8243, '1 Kings 2:10', '1 Kings', 2, 10, '&nbsp;نو داؤد وفات شو او د داؤد په ښار کښې ښخ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8244, '1 Kings 2:11', '1 Kings', 2, 11, '&nbsp;څلوېښت کاله هغه د بنى اِسرائيلو بادشاه وو، اووۀ کاله يې په حبرون کښې او درې دېرش کاله يې په يروشلم کښې بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8245, '1 Kings 2:12', '1 Kings', 2, 12, '&nbsp;سليمان د خپل پلار داؤد نه پس بادشاه شو او د هغۀ بادشاهى مضبوطه قائمه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8246, '1 Kings 2:13', '1 Kings', 2, 13, '&nbsp;بيا ادونياه چې د هغۀ مور حجيت وه، بت‌‌سبع له لاړه چې هغه د سليمان مور وه. هغې ترې نه تپوس وکړو، ”تۀ د خېر دپاره راغلې؟“ هغۀ ورته ووئيل، ”آو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8247, '1 Kings 2:14', '1 Kings', 2, 14, '&nbsp;هغۀ بيا دا هم ووئيل، ”زۀ تا ته يو عرض کوم.“ هغې ورته ووئيل، ”څۀ دى، ووايه؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8248, '1 Kings 2:15', '1 Kings', 2, 15, '&nbsp;هغۀ ورته ووئيل، ”تا ته پته ده چې بادشاهى زما حق وو او ټولو بنى اِسرائيلو غوښتل چې زۀ بادشاه جوړ شم. خو خبره بدله شوه او زما ورور بادشاه شو، ځکه چې دا د مالِک خُدائ مرضى وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8249, '1 Kings 2:16', '1 Kings', 2, 16, '&nbsp;او اوس زۀ يو عرض کول غواړم، مِهربانى وکړه چې اِنکار ونۀ کړې.“ بت‌‌سبع ورته ووئيل، ”ووايه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8250, '1 Kings 2:17', '1 Kings', 2, 17, '&nbsp;هغۀ ورته ووئيل، ”مِهربانى وکړه چې سليمان بادشاه ته ووايه، ما ته پته ده چې هغه به تا ته اِنکار نۀ کوى، چې هغه ما پرېږدى چې شونيمى ښځه ابى‌شاګ وادۀ کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8251, '1 Kings 2:18', '1 Kings', 2, 18, '&nbsp;هغې ورته ووئيل، ”ټيک ده، زۀ به د بادشاه سره ستا دپاره خبره وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8252, '1 Kings 2:19', '1 Kings', 2, 19, '&nbsp;نو بت‌‌سبع بادشاه له لاړه چې د هغۀ سره د ادونياه دپاره خبره وکړى. بادشاه پاڅېدو چې خپلې مور ته ستړى مشى وکړى او د هغې په مخکښې ټيټ شو. بيا هغه په خپل تخت کښېناستو او د هغې دپاره يې بل تخت راوړو چې د هغۀ ښى طرف ته هغه پرې کښېنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8253, '1 Kings 2:20', '1 Kings', 2, 20, '&nbsp;هغې ورته ووئيل، ”زۀ غواړم چې تۀ زما سره يوه معمولى شان نېکى وکړې، مِهربانى وکړه چې ما ته اِنکار ونۀ کړې.“ هغۀ ورته وفرمائيل، ”زما مورې، څۀ وئيل غواړې، زۀ به تا ته اِنکار نۀ کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8254, '1 Kings 2:21', '1 Kings', 2, 21, '&nbsp;هغې ورته ووئيل، ”خپل ورور ادونياه پرېږده چې د ابى‌شاګ سره وادۀ وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8255, '1 Kings 2:22', '1 Kings', 2, 22, '&nbsp;بادشاه ترې نه تپوس وکړو، ”تۀ ما ته دا څنګه وائې چې ابى‌شاګ ادونياه له ورکړم؟ کېدے شى دا هم راته ووائې چې هغۀ له تخت هم ورکړه، ځکه چې هغه خو زما مشر ورور دے او ابياتار اِمام او يوآب د هغۀ په طرف دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8256, '1 Kings 2:23', '1 Kings', 2, 23, '&nbsp;بيا سليمان د مالِک خُدائ په نوم يو پوخ لوظ وکړو، ”کۀ ما ادونياه ژوندے پرېښودو نو خُدائ پاک دې ما ووژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8257, '1 Kings 2:24', '1 Kings', 2, 24, '&nbsp;مالِک خُدائ زۀ د خپل پلار داؤد په تخت مقرر کړے او کښېنولے يم، هغۀ خپله وعده پوره کړې ده او ما او زما اولاد له يې بادشاهى راکړې ده. زۀ په مالِک خُدائ قسم کوم چې نن به ادونياه وژلے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8258, '1 Kings 2:25', '1 Kings', 2, 25, '&nbsp;نو سليمان بناياه له حُکم ورکړو، هغه لاړو او ادونياه يې ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8259, '1 Kings 2:26', '1 Kings', 2, 26, '&nbsp;بيا سليمان ابياتار اِمام ته وفرمائيل، ”تۀ په عنتوت کښې خپل مُلک ته لاړ شه. تۀ د مرګ حقدار يې، خو زۀ به تا اوس نۀ وژنم، ځکه چې تۀ کله زما د پلار داؤد سره وې نو د مالِک خُدائ د لوظ صندوق ذمه وار وې او تۀ د هغۀ سره په ټولو تکليفونو کښې شريک وې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8260, '1 Kings 2:27', '1 Kings', 2, 27, '&nbsp;بيا سليمان ابياتار د مالِک خُدائ د اِمامت د خِدمت نه لرې کړو، نو داسې چې مالِک خُدائ په سيلا کښې د عيلى اِمام او د هغۀ د اولاد په حقله څۀ فرمائيلى وُو هغه يې رښتيا کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8261, '1 Kings 2:28', '1 Kings', 2, 28, '&nbsp;يوآب په مخکښېنى بغاوت کښې د ابى‌سلوم ملګرتيا نۀ وه کړې، خو د ادونياه د بغاوت ملګرتيا يې کړې وه. کله چې يوآب د ادونياه د مرګ نه خبر شو، نو يوآب د مالِک خُدائ د حضور خېمې ته وتښتېدو او د قربان‌ګاه ښکر يې ونيول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8262, '1 Kings 2:29', '1 Kings', 2, 29, '&nbsp;کله چې سليمان خبر شو چې يوآب قربان‌ګاه ته تښتېدلے دے نو سليمان يو پېغام وړونکے ورولېږلو چې تپوس ترې نه وکړى چې قربان‌ګاه ته ولې تښتېدلے يې. يوآب ورته ووئيل چې زۀ مالِک خُدائ له ځکه راتښتېدلے يم چې زۀ د سليمان نه يرېدم. نو سليمان بادشاه بناياه ورولېږلو چې يوآب ووژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8263, '1 Kings 2:30', '1 Kings', 2, 30, '&nbsp;بناياه د مالِک خُدائ د حضور خېمې ته لاړو او يوآب ته يې ووئيل، ”بادشاه تا ته حُکم کوى چې بهر راووځه.“ يوآب ورته ووئيل، ”نۀ، زۀ به دلته مرم.“ بناياه واپس بادشاه له لاړو او چې يوآب څۀ وئيلى وُو هغه يې ورته ووئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8264, '1 Kings 2:31', '1 Kings', 2, 31, '&nbsp;سليمان ورته ووئيل ”هم هغه شان وکړه چې څنګه هغه وائى. هغه ووژنه او ښخ يې کړه، نو داسې ما او زما د پلار کور د هغه ګناه نه پاک کړه چې کومه بې‌ګناه وينه يوآب توئ کړې وه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8265, '1 Kings 2:32', '1 Kings', 2, 32, '&nbsp;او مالِک خُدائ به د دې قتلونو په وجه يوآب له سزا ورکړى، کوم يې چې زما د پلار داؤد په ناخبرۍ کښې کړى وُو. يوآب دوه بې‌ګناه سړى ووژل چې د هغۀ نه ښۀ وُو يعنې، ابنير چې د بنى اِسرائيلو د لښکر مشر وو او عماسا چې د يهوداه د لښکر مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8266, '1 Kings 2:33', '1 Kings', 2, 33, '&nbsp;د هغوئ د قتل ټوله سزا به په يوآب او د هغۀ د اولاد په غاړه د تل دپاره وى. خو مالِک خُدائ به داؤد، د هغۀ اولاد، خاندان او د هغۀ بادشاهۍ له تل خېر ورکوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8267, '1 Kings 2:34', '1 Kings', 2, 34, '&nbsp;نو بناياه د مالِک خُدائ د حضور خېمې له لاړو او يوآب يې ووژلو او هغه په صحرا کښې د خپل کور سره ښخ کړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8268, '1 Kings 2:35', '1 Kings', 2, 35, '&nbsp;نو بادشاه د يوآب په ځائ بناياه د فوج مشر جوړ کړو او صدوق اِمام يې د ابياتار په ځائ مشر جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8269, '1 Kings 2:36', '1 Kings', 2, 36, '&nbsp;نو بادشاه سِمعى راوغوښتو او ورته يې وفرمائيل، ”دلته په يروشلم کښې د ځان دپاره کور جوړ کړه. په هغې کښې اوسېږه او د دې ښار نه چرته هم مۀ ځه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8270, '1 Kings 2:37', '1 Kings', 2, 37, '&nbsp;کۀ تۀ کله هم لاړ شې او د قِدرون ولې نه واوړې نو دا پخه خبره ده چې تۀ به خامخا مړ شې او خُون به ستا په خپله غاړه وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8271, '1 Kings 2:38', '1 Kings', 2, 38, '&nbsp;سِمعى ورته ووئيل، ”بادشاه سلامت، تا ډېره ښۀ خبره وکړه، تۀ چې څۀ غواړې نو زۀ به هم هغه کوم.“ نو هغه تر ډېر وخت پورې په يروشلم کښې اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8272, '1 Kings 2:39', '1 Kings', 2, 39, '&nbsp;درې کاله وروستو، د سِمعى دوه غلامان د جات بادشاه د معکه زوئ اکيس له وتښتېدل. نو چې سِمعى خبر شو چې هغوئ په جات کښې دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8273, '1 Kings 2:40', '1 Kings', 2, 40, '&nbsp;نو هغۀ خپل خر کته کړو او په جات کښې اکيس بادشاه له لاړو، چې خپل غلامان ولټوى. هغوئ يې پېدا کړل او واپس يې خپل کور ته راوستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8274, '1 Kings 2:41', '1 Kings', 2, 41, '&nbsp;کله چې سليمان خبر شو چې سِمعى څۀ کړى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8275, '1 Kings 2:42', '1 Kings', 2, 42, '&nbsp;نو سِمعى يې راوغوښتو او ورته يې وفرمائيل، ”ستا نه ما د مالِک خُدائ په نوم لوظ نۀ وو اخستے چې تۀ به د يروشلم نه نۀ وځې؟ او ما سخت خبردارے درکړو کۀ تا کله هم داسې وکړل نو خامخا به مړ شې. ولې تۀ په دې باندې ما سره راضى شوے نۀ وې څۀ چې زما حُکم به منې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8276, '1 Kings 2:43', '1 Kings', 2, 43, '&nbsp;نو بيا تا ولې د مالِک خُدائ سره خپله وعده ماته کړې ده او زما د حُکم نافرمانى دې کړې ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8277, '1 Kings 2:44', '1 Kings', 2, 44, '&nbsp;تا ته د هغه ټولو بدو عملونو ډېره ښۀ پته ده چې تا زما پلار داؤد سره کړى دى. مالِک خُدائ به د دې په بدل کښې سزا درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8278, '1 Kings 2:45', '1 Kings', 2, 45, '&nbsp;خو هغه به ما له برکت راکړى او د داؤد بادشاهى به د همېشه دپاره په امن کښې کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8279, '1 Kings 2:46', '1 Kings', 2, 46, '&nbsp;بيا بادشاه بناياه له حُکم ورکړو او بناياه لاړو او سِمعى يې ووژلو. بادشاهى اوس په پوره توګه د سليمان په قابو کښې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8280, '1 Kings 3:1', '1 Kings', 3, 1, '&nbsp;سليمان د مِصر بادشاه فِرعون سره اِتحاد وکړو او د هغۀ لور يې وادۀ کړه. هغه يې د داؤد ښار ته راوستله او تر هغې پورې هلته اوسېدله چې ترڅو پورې هغۀ خپل محل، د مالِک خُدائ کور او د يروشلم ګېرچاپېره دېوال جوړول ختم کړى نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8281, '1 Kings 3:2', '1 Kings', 3, 2, '&nbsp;د مالِک خُدائ کور تر اوسه پورې نۀ وو جوړ شوے، نو ځکه خلقو په علاقائى عبادتخانو کښې قربانۍ پېش کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8282, '1 Kings 3:3', '1 Kings', 3, 3, '&nbsp;سليمان د مالِک خُدائ سره مينه کوله او د خپل پلار داؤد په خبرو يې عمل کولو، خو هغۀ هم په علاقائى عبادتخانې کښې خوشبويۍ سوزولې او قربانۍ يې پېش کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8283, '1 Kings 3:4', '1 Kings', 3, 4, '&nbsp;يوه ورځ هغه د قربانۍ پېش کولو دپاره جبعون ته لاړو چرته چې د قربانۍ مرکزى ځائ وو. هغۀ هلته يو زر سوزېدونکې نذرانې پېش کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8284, '1 Kings 3:5', '1 Kings', 3, 5, '&nbsp;په هغه شپه مالِک خُدائ هغۀ ته په خوب کښې څرګند شو او تپوس يې ترې نه وکړو، ”تۀ څۀ غواړې چې زۀ يې درکړم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8285, '1 Kings 3:6', '1 Kings', 3, 6, '&nbsp;سليمان ورته وفرمائيل، ”تا زما پلار خپل خِدمت کوونکى داؤد ته همېشه ډېره مينه ښودلې ده او هغه په خپل تعلق کښې تا سره نېک، وفادار او صادق وو. تۀ هغۀ ته خپله لويه او نۀ بدلېدونکې مينه تر اوسه پورې ښائې چې هغۀ له دې يو زوئ ورکړو کوم چې د هغۀ په ځائ نن په تخت ناست دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8286, '1 Kings 3:7', '1 Kings', 3, 7, '&nbsp;مالِکه خُدايه، زما خُدائ پاکه، تا زۀ د خپل پلار نه پس بادشاه جوړ کړے يم، اګر چې زۀ د يو وړوکى ماشوم په شان يم او په هيڅ هم نۀ پوهېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8287, '1 Kings 3:8', '1 Kings', 3, 8, '&nbsp;زۀ دلته د هغه خلقو په مينځ کښې يم چې تا د خپل ځان دپاره غوره کړى دى. هغه قوم دومره لوئ دے چې د شمېر نه بهر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8288, '1 Kings 3:9', '1 Kings', 3, 9, '&nbsp;نو ما له حِکمت راکړه چې ستا په خلقو باندې په اِنصاف سره بادشاهى وکړم او د ښۀ او بد په مينځ کښې فرق وپېژنم. ګنې زۀ به څنګه د دې جوګه شم چې ستا په لوئ قوم باندې بادشاهى وکړم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8289, '1 Kings 3:10', '1 Kings', 3, 10, '&nbsp;مالِک خُدائ د سليمان په دې غوښتنه باندې خوشحاله شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8290, '1 Kings 3:11', '1 Kings', 3, 11, '&nbsp;نو هغۀ ورته وفرمائيل، ”تا حِکمت غوښتلے دے چې په اِنصاف سره بادشاهى وکړې او خپل اوږد عُمر، مالدارى او د خپل دشمن مرګ دې نۀ دے غوښتے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8291, '1 Kings 3:12', '1 Kings', 3, 12, '&nbsp;نو په دې وجه به زۀ هغه څۀ وکړم چې تا غوښتى دى. زۀ به تا له دومره ډېر حِکمت او پوهه درکړم چې نۀ به چا ته مخکښې مِلاو شوې وى او نۀ به تا نه وروستو چا ته مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8292, '1 Kings 3:13', '1 Kings', 3, 13, '&nbsp;زۀ به تا له هغه څۀ هم درکړم چې تا نۀ دى غوښتى، ترڅو پورې چې تۀ ژوندے يې نو تۀ به دولتمند او عزتمند يې، نو داسې تۀ به د ټولو بادشاهانو نه لوئ بادشاه يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8293, '1 Kings 3:14', '1 Kings', 3, 14, '&nbsp;او کۀ تۀ د خپل پلار داؤد په شان زما تابعدارى کوې او زما قانون او حُکمونه پوره کوې، نو زۀ به تا له يو اوږد عُمر درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8294, '1 Kings 3:15', '1 Kings', 3, 15, '&nbsp;سليمان راويښ شو او پته ورته ولګېده چې خُدائ پاک ورسره په خوب کښې خبرې وکړې. بيا هغه يروشلم ته لاړو او د مالِک خُدائ د لوظ صندوق په مخکښې ودرېدو او مالِک خُدائ ته يې سوزېدونکې نذرانې او د سلامتۍ نذرانې پېش کړې. او د خپلو درباريانو دپاره يې يوه لويه مېلمستيا وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8295, '1 Kings 3:16', '1 Kings', 3, 16, '&nbsp;يوه ورځ دوه کنجرې ښځې راغلې او سليمان بادشاه په مخکښې يې خپل ځانونه پېش کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8296, '1 Kings 3:17', '1 Kings', 3, 17, '&nbsp;هغې يوې په کښې ووئيل، ”بادشاه سلامت، دا ښځه او زۀ په يو کور کښې اوسيږو او چې دا کله هلته وه نو زما يو ماشوم پېدا شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8297, '1 Kings 3:18', '1 Kings', 3, 18, '&nbsp;زما د زوئ د پېدا کېدو په درېمه ورځ د هغې هم يو ماشوم پېدا شو. په هغه کور کښې صِرف زۀ او هغه وُو او بل هيڅ څوک هم موجود نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8298, '1 Kings 3:19', '1 Kings', 3, 19, '&nbsp;نو يوه شپه هغه په غلطۍ سره هغې خپل ماشوم د اړخ لاندې کړو او د هغۀ ساه يې بنده کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8299, '1 Kings 3:20', '1 Kings', 3, 20, '&nbsp;هغه د شپې پاڅېده، چې کله زۀ اوده وم نو هغې زما نه ماشوم واخستلو او په خپل څنګ کښې يې واچولو، بيا هغې هغه مړ ماشوم زما په کټ کښې کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8300, '1 Kings 3:21', '1 Kings', 3, 21, '&nbsp;په ورپسې سحر کله چې زۀ پاڅېدم او خپل ماشوم له مې تے ورکولو، نو ومې ليدل چې دا خو مړ دے. ما په رڼا کښې ښۀ په غور سره ورته وکتل او پته راته ولګېده چې دا خو زما ماشوم نۀ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');